// Example A: for-await-of with dedupe helper
const stream = client.stream({ model: 'rw-instruct-7b' });
for await (const chunk of stream.asAsyncIterable()) {
  renderChunk(chunk.text);
}
// Example B: browser pipeTo usage
const stream = client.stream({ model: 'rw-chat-3b' });
const rs = stream.asReadableStream();
const encoder = new TextEncoderStream();
rs.pipeThrough(encoder).pipeTo(new WritableStream({ write(chunk) { appendToLog(chunk); } }));
// Example C: cancellation pattern
const s = client.stream(params);
const iter = s.asAsyncIterable()[Symbol.asyncIterator]();
setTimeout(async () => {
  // user navigated away
  await s.cancel(); // ensures transport is closed and resources freed
}, 2000);
